mapper.select:
select po.id, po.order_no, po.order_status, po.order_time, po.pet_name,
po.pet_img, po.pet_price, po.consignee, po.phone_number, po.province_code, po.city_code,
po.district_code, po.detail_address,u.nickname as userNickname,ps.nickname as shopName
from pet_orders po
left join user u on po.user_id = u.id
left join pet_shop ps on po.shop_id = ps.id

    and po.order_no = #{orderNo}
    and po.order_status = #{orderStatus}
    and po.order_time > #{orderTime}
    and po.shop_id = #{shopId}

order by po.order_time desc

select id,
       order_status
from pet_orders
where order_status = #{orderStatus}
  and order_time < #{time}

select coalesce(sum(po.pet_price), 0) from (
select #{date} date
) d left join pet_orders po on date(po.order_time) = d.date and po.order_status != 5 and po.shop_id = #{shopId} group by d.date order by d.date

select count(po.id) as totalNumber, count(case when po.order_status != 5 then po.id end) as validNumber from (
select #{date} as date
) d left join pet_orders po on date(po.order_time) = d.date and po.shop_id = #{shopId} group by d.date order by d.date

select count(*)
from pet_orders
where shop_id = #{shopId}
  and order_status = #{orderStatus}
